 schema={'type':'object','properties':{'evidence_group':{'type':'string','enum':['clinical','review','preclinical','unresolved_or_other']},'topical_role':{'type':'string','enum':['primary','secondary_substantive','background_only','unresolved']},'design_paragraph_index':{'type':'integer','enum':ids},'topic_paragraph_index':{'type':'integer','enum':ids}},'required':['evidence_group','topical_role','design_paragraph_index','topic_paragraph_index'],'additionalProperties':False}
 request={'model':runner.MODEL,'stream':False,'think':False,'format':schema,'keep_alive':'5m','options':{'temperature':0,'seed':20261003,'num_ctx':8192,'num_predict':128},'messages':[{'role':'system','content':runner.PROMPT},{'role':'user','content':text}]};assert hashlib.sha256(json.dumps(request,sort_keys=True).encode()).hexdigest()==r['request_sha256'];v=r['response'];assert v['done'] is True and 0<v['prompt_eval_count']<=7680 and v['eval_count']<=128;parsed=json.loads(r['raw']);assert parsed==r['parsed'] and set(parsed)==set(schema['required']) and r['transport_and_location_valid'] is True
