 counts['both']+=all(parsed[k]==ref[k] for k in ['evidence_group','topical_role']);compact.append({'pmcid':r['pmcid'],'prediction':parsed,'draft_reference':{k:ref[k] for k in ['evidence_group','topical_role']},'elapsed_seconds':r['elapsed_seconds'],'source_context_sha256':r['context_sha256'],'narrative_character_coverage':r['narrative_characters_submitted']/r['narrative_characters_available'],'training_admission':False})
