out={'status':'audited_complete_rejected_for_topic_scaling','cases':6,'transport_and_source_location_valid':6,'agreement_with_draft_references':counts,'compact_decisions':compact,'raw_rows_sha256':sha(stage/'rows.jsonl'),'raw_result_sha256':sha(stage/'result.json'),'manifest_sha256':sha(stage/'manifest.json'),'cumulative_broad_local_elapsed_seconds':result['elapsed_seconds']+m['prior_elapsed_seconds'],'combined_attempted_ids':7,'combined_received_responses':6,'remaining_unattempted_ids':17,'training_admission':False,'decision':'Operationally feasible shorter response, but all six predicted primary: two draft background-only and one secondary case misclassified. Do not scale or admit sources with this topic classifier.','limitations':'Six purposively selected development sources and single-agent references, not expert-gold/representative accuracy. Exact IDs do not prove evidence entailment. Multiple settings differ; no isolated causal comparison. Expansion paused for CV gap closure.'};p=imp/'gemma_broad_remaining_audit_2026-10-03.json';assert not p.exists();p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(counts))
